 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Select the unique filled 3x3 tile that uses three colors; the other
    # tiles use only two colors.
    candidates = []
    for r in range(h - 2):
        for c in range(w - 2):
            tile = [row[c:c + 3] for row in grid[r:r + 3]]
            colors = {v for row in tile for v in row}
            if 0 not in colors and len(colors) == 3:
                candidates.append(tile)
    if len(candidates) != 1:
        raise ValueError(f"expected one three-color 3x3 tile, got {len(candidates)}")
    return candidates[0]
